SELECT s.city, CASE WHEN s.rating >= 3.5 THEN 'high' WHEN s.rating >= 2.6 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(*) AS inventory_count FROM inventory i JOIN products p ON i.product_id = p.id LEFT OUTER JOIN suppliers s ON p.supplier_id = s.id GROUP BY s.city, CASE WHEN s.rating >= 3.5 THEN 'high' WHEN s.rating >= 2.6 THEN 'mid' ELSE 'low' END HAVING COUNT(*) >= 5 ORDER BY city
